SELECT "nct", "author", "year", "pubmed_id", "trial_phase", "treatment_regimen", "name_of_ici", "class_of_ici", "type_of_combination", "control_regimen", "clinical_setting" FROM public."clinical_trials" WHERE "trial_phase" = '3' AND "class_of_ici" = 'PD1' AND "cancer_type" = 'Multiple Myeloma' AND "type_of_combination" IS NOT NULL;